@startuml

class Car {
  + licensePlate : string
}

class Owner {
  + name : string
}

class Accident {
  + date : date
  + location : string
  + damageAmount : double
}

class RideHail {
  + pickUpTime : time
  + dropOffTime : time
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : string
  + distance : double
  + passengerCount : int
  + fee : double
  + requestType : string
}

class RideShare {
  + pickUpTime : time
  + dropOffTime : time
  + pickUpLocation : string
  + dropOffLocation : string
  + duration : string
  + distance : double
  + upfrontFee : double
}

class Customer {
  + name : string
}

Car "1" -- "*" Accident
Car "1" -- "0..1" Owner : owned by
Car "1" -- "*" RideHail
Car "1" -- "*" RideShare
RideHail "*" -- "1" Customer : lead customer
RideShare "*" -- "1..10" Customer : passengers

@enduml

